INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','passive-voice','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"passive-voice","title":"Passive voice: focus on the receiver","level":"B1","order":48,"summary":"Change the focus of a clause while keeping its tense and meaning clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Change the starting point","Keep the original tense","Continuous and perfect passives","Negatives, questions and modals"],"rules":[{"title":"Change the starting point","explanation":"A passive clause makes the receiver or affected participant the subject. Build it with **be + past participle**. A by phrase can name the agent when that information matters, but it is often omitted when unknown or obvious.","pattern":"The report **was checked** by the editor.","commonMistakes":["An intransitive verb such as arrive normally has no object to turn into a passive subject."],"examples":["Use present simple passive: “The visitor guide **is prepared** every week.”","Use present simple passive: “The old portrait **is restored** every week.”"],"skill":"form"},{"title":"Keep the original tense","explanation":"The form of **be** carries tense and agreement. The past participle stays the same. Present simple passive uses am/is/are; past simple passive uses was/were. Find the new subject’s number before choosing be.","pattern":"The letters **are delivered**. / The letter **was delivered**.","commonMistakes":["A past participle is not a past-tense marker by itself: is delivered is present passive."],"examples":["Use past simple passive: “The visitor guide **was prepared** yesterday.”","Use past simple passive: “The old portrait **was restored** yesterday.”"],"skill":"meaning"},{"title":"Continuous and perfect passives","explanation":"A continuous passive adds being before the participle. A perfect passive adds been after have. Read the chain from left to right: first tense, then aspect, then passive.","pattern":"It **is being repaired**. / It **has been repaired**.","commonMistakes":["Being and been are not interchangeable: continuous uses being; perfect uses been."],"examples":["Use present continuous passive: “The visitor guide is **being prepared** right now.”","Use present continuous passive: “The old portrait is **being restored** right now.”"],"skill":"contrast"},{"title":"Negatives, questions and modals","explanation":"Put not after the first auxiliary and move that auxiliary before the subject in questions. A modal passive uses modal + be + participle. Do not add do to a passive that already contains be.","pattern":"**Was** it repaired? / It **must be repaired**.","commonMistakes":["A passive is a choice of focus, not automatically better or more formal than active voice."],"examples":["Use a modal passive: “The visitor guide must **be prepared** before Friday.”","Use a modal passive: “The old portrait must **be restored** before Friday.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"90a4096e-3d7e-58e7-a642-974220c1688f","topicSlug":"passive-voice","level":"B1","prompt":"Use present simple passive: “The visitor guide ____ every week.”","choices":[{"id":"A","text":"is to prepare"},{"id":"B","text":"is prepared"},{"id":"C","text":"is preparing"},{"id":"D","text":"are prepared"}],"answerId":"B","hint":"The task asks for **receiver + present be + past participle**.","explanation":"The singular/uncountable subject takes **is**, followed by participle **prepared**.","keywords":["present-passive"],"skill":"present-passive","contextKey":"passive-voice-1","fingerprint":"3ff7adadedd14efa069ba4a81514937a261328268caae8aef9605b2a7fc44d69","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The task asks for **receiver + present be + past participle**.","The singular/uncountable subject takes **is**, followed by participle **prepared**.","Choose **is prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is not the present-simple passive construction.","B":"The singular/uncountable subject takes **is**, followed by participle **prepared**.","C":"This is active continuous, not passive.","D":"This form of be does not agree with the subject."}}},{"id":"2cad457f-041d-5b4a-a606-27a5b7d37cd2","topicSlug":"passive-voice","level":"B1","prompt":"Use past simple passive: “The visitor guide ____ yesterday.”","choices":[{"id":"A","text":"did prepared"},{"id":"B","text":"was prepared"},{"id":"C","text":"were prepared"},{"id":"D","text":"was preparing"}],"answerId":"B","hint":"The event is past and the subject receives the action.","explanation":"Past simple passive with this subject is **was prepared**.","keywords":["past-passive"],"skill":"past-passive","contextKey":"passive-voice-1","fingerprint":"5ecec409f27ef72ae353d9dd7aa6a99df12fee37f19c01bd607926566e2612a4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The event is past and the subject receives the action.","Past simple passive with this subject is **was prepared**.","Choose **was prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did cannot replace passive be before a participle.","B":"Past simple passive with this subject is **was prepared**.","C":"This form of be does not agree with the subject in this factual clause.","D":"This is active past continuous, not passive."}}},{"id":"fda35322-ec25-5154-a5a1-f2ee78cc3c48","topicSlug":"passive-voice","level":"B1","prompt":"Use present continuous passive: “The visitor guide is ____ right now.”","choices":[{"id":"A","text":"being prepared"},{"id":"B","text":"been prepared"},{"id":"C","text":"prepared"},{"id":"D","text":"being preparing"}],"answerId":"A","hint":"Ongoing passive = **be + being + past participle**.","explanation":"After the finite form of be, **being prepared** marks an ongoing passive action.","keywords":["continuous-passive"],"skill":"continuous-passive","contextKey":"passive-voice-1","fingerprint":"8c3f19a9a72b2b42f254d82beca0f87af5a077aabdc05021525be79127e36c4f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ongoing passive = **be + being + past participle**.","After the finite form of be, **being prepared** marks an ongoing passive action.","Choose **being prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After the finite form of be, **being prepared** marks an ongoing passive action.","B":"Been belongs after perfect have, not directly after is.","C":"This makes simple passive, not the requested continuous passive.","D":"The passive part needs a past participle after being."}}},{"id":"72451484-f163-5f91-a65a-0a6ae8cdc0eb","topicSlug":"passive-voice","level":"B1","prompt":"Use a modal passive: “The visitor guide must ____ before Friday.”","choices":[{"id":"A","text":"be preparing"},{"id":"B","text":"be prepared"},{"id":"C","text":"been prepared"},{"id":"D","text":"is prepared"}],"answerId":"B","hint":"The object receives the required action: **must be + participle**.","explanation":"After must, use base **be** and participle **prepared**.","keywords":["modal-passive"],"skill":"modal-passive","contextKey":"passive-voice-1","fingerprint":"c8f9b55f1d4c624294347eb5c70340a0687590f11fa29a697209690a01d67da6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object receives the required action: **must be + participle**.","After must, use base **be** and participle **prepared**.","Choose **be prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is active continuous, not passive.","B":"After must, use base **be** and participle **prepared**.","C":"Must needs have before been; this task asks for a simple modal passive.","D":"A finite is cannot follow must."}}},{"id":"bbeb882f-13aa-5191-a545-d354c6367809","topicSlug":"passive-voice","level":"B1","prompt":"Use present simple passive: “The old portrait ____ every week.”","choices":[{"id":"A","text":"is restoring"},{"id":"B","text":"are restored"},{"id":"C","text":"is to restore"},{"id":"D","text":"is restored"}],"answerId":"D","hint":"The task asks for **receiver + present be + past participle**.","explanation":"The singular/uncountable subject takes **is**, followed by participle **restored**.","keywords":["present-passive"],"skill":"present-passive","contextKey":"passive-voice-2","fingerprint":"411bae37243e3deb30513cb3165efd4424a3c141606d145ce23ea65574bbdc8b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The task asks for **receiver + present be + past participle**.","The singular/uncountable subject takes **is**, followed by participle **restored**.","Choose **is restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is active continuous, n